input.content:
workspace "Claims Center" "Insurance claims platform" {

    !identifiers hierarchical

    model {
        # People
        policyholder = person "Policyholder" "Reports claims and tracks their progress"
        adjuster = person "Adjuster" "Processes assigned claims"

        # External systems
        claimsDataBureau = softwareSystem "National Claims Data Bureau" "A national claims data bureau operated by a different organization" "External"
        clearingHouse = softwareSystem "Clearing House" "A clearing house operated by a different organization" "External"

        # Main system
        claimsCenter = softwareSystem "Claims Center" "Insurance claims platform owned and operated by the insurance company" {
            webPortal = container "Web Portal" "Where policyholders report claims and track their progress" {
                tags "Web"
            }
            mobileAppBackend = container "Mobile App Backend" "Serves the insurer's mobile app"
            claimsIntake = container "Claims Intake Service" "Registers new claims"
            triage = container "Triage Service" "Classifies and prioritizes claims"
            assessment = container "Assessment Service" "Calculates settlement amounts"
            payout = container "Payout Service" "Executes claim settlements"
            fraudScreening = container "Fraud Screening Service" "Flags suspicious claims"
            documentService = container "Document Service" "Accepts claim photos and reports"
            notification = container "Notification Service" "Emails and messages policyholders"
            assignment = container "Assignment Service" "Routes claims to adjusters"
            adjusterWorkbench = container "Adjuster Workbench" "Where staff process their assigned claims"
            policyVerification = container "Policy Verification Service" "Checks that a claim is covered by the policy"
            reinsuranceAllocation = container "Reinsurance Allocation Service" "Apportions large losses across reinsurance partners"
            batchScheduler = container "Batch Scheduler" "Runs the nightly reserves calculation"
            eventQueue = container "Event Queue" "Carries claim events between the application parts" {
                tags "Queue"
            }
            claimsDb = container "Claims Database" "Stores claim records" {
                tags "Database"
            }
            policyDb = container "Policy Database" "Stores policy and cover records" {
                tags "Database"
            }
            auditDb = container "Audit Database" "Stores the compliance audit trail" {
                tags "Database"
            }
            documentStore = container "Document Store" "Holds claim photos, reports, and correspondence" {
                tags "Database"
            }
        }

        # Relationships
        policyholder -> claimsCenter.webPortal "reports claims and tracks progress"
        policyholder -> claimsCenter.mobileAppBackend "reports claims and tracks progress"
        adjuster -> claimsCenter.adjusterWorkbench "processes assigned claims"

        claimsCenter.webPortal -> claimsCenter.claimsIntake "submits new claims to"
        claimsCenter.webPortal -> claimsCenter.assessment "requests settlement amounts from"
        claimsCenter.webPortal -> claimsCenter.payout "requests settlements from"
        claimsCenter.webPortal -> claimsCenter.documentService "uploads claim photos and reports to"
        claimsCenter.webPortal -> claimsCenter.notification "requests status notifications from"

        claimsCenter.mobileAppBackend -> claimsCenter.claimsIntake "submits new claims to"
        claimsCenter.mobileAppBackend -> claimsCenter.assessment "requests settlement amounts from"
        claimsCenter.mobileAppBackend -> claimsCenter.payout "requests settlements from"
        claimsCenter.mobileAppBackend -> claimsCenter.documentService "uploads claim photos and reports to"
        claimsCenter.mobileAppBackend -> claimsCenter.notification "requests status notifications from"

        claimsCenter.claimsIntake -> claimsCenter.triage "hands accepted claims to"
        claimsCenter.triage -> claimsCenter.assessment "routes claims to"
        claimsCenter.assessment -> claimsCenter.payout "requests settlements from"

        claimsCenter.claimsIntake -> claimsCenter.fraudScreening "sends incoming claims for screening"
        claimsCenter.claimsIntake -> claimsCenter.policyVerification "sends claims for cover verification"
        claimsCenter.claimsIntake -> claimsCenter.assignment "sends claims for assignment"
        claimsCenter.assignment -> claimsCenter.adjusterWorkbench "routes claims to"

        claimsCenter.documentService -> claimsCenter.documentStore "reads from"
        claimsCenter.batchScheduler -> claimsCenter.claimsDb "reads and writes"
        claimsCenter.batchScheduler -> claimsCenter.policyDb "reads and writes"
        claimsCenter.notification -> policyholder "sends claim status updates by email and message"

        claimsCenter.fraudScreening -> claimsDataBureau "consults claims data"
        claimsCenter.payout -> clearingHouse "executes settlements through"
    }

    views {
        systemContext claimsCenter "SystemContext" {
            include *
            autoLayout
            title "System Context for Claims Center"
        }

        container claimsCenter "Containers" {
            include *
            autoLayout
            title "Containers for Claims Center"
        }

        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Database" {
                shape Cylinder
            }
            element "Queue" {
                shape Pipe
            }
            element "Web" {
                shape WebBrowser
            }
        }
    }
}

